import{_ as t}from"./chunks/log-bb-player.pc.ko.BXBA5pF-.js";import{_ as r,o as s,c as n,a5 as a}from"./chunks/framework.BjM_ivYE.js";const l="/RBQ/images/app/log-rt.pc.ko.png",e="/RBQ/images/app/log-sys.pc.ko.png",f=JSON.parse('{"title":"로그","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/logs.md","filePath":"ko/manual/gui/logs.md","lastUpdated":1790651576000}'),g={name:"ko/manual/gui/logs.md"};function i(d,o,c,h,p,m){return s(),n("div",null,[...o[0]||(o[0]=[a('<h1 id="로그" tabindex="-1">로그 <a class="header-anchor" href="#로그" aria-label="Permalink to &quot;로그&quot;">​</a></h1><p><strong>로그</strong>는 메뉴에 따로 없습니다 — 제어 홈에서 빨간 <strong>ERROR</strong> / <strong>FATAL</strong> 토스트나 경고 배지 팝오버의 행을 누르면 열립니다(<a href="#real-time">Real Time</a> 참고). 누구나 열 수 있는 화면입니다. 탭이 세 개 있고, 필터 바는 어느 탭에서나 똑같이 동작합니다.</p><p><img src="'+l+'" alt="Real Time 탭"></p><h2 id="탭" tabindex="-1">탭 <a class="header-anchor" href="#탭" aria-label="Permalink to &quot;탭&quot;">​</a></h2><table tabindex="0"><thead><tr><th>탭</th><th>내용</th></tr></thead><tbody><tr><td><strong>Real Time</strong></td><td>앱이 연결된 동안 로봇에서 실시간으로 들어오는 메시지</td></tr><tr><td><strong>System Log</strong></td><td>로봇에 하루 단위로 저장된 로그 파일</td></tr><tr><td><strong>Black Box</strong></td><td>로봇이 넘어졌거나 제어가 꺼졌거나 <strong>지금 저장</strong>을 눌렀을 때 저장되는 기록 — 30초 분량의 모션 데이터와 그 시점의 시스템 로그</td></tr></tbody></table><p>탭 옆의 점은 로그 링크 상태를 알려 줍니다: <strong>연결됨</strong>, <strong>연결 중</strong>, <strong>끊김</strong>.</p><h2 id="필터" tabindex="-1">필터 <a class="header-anchor" href="#필터" aria-label="Permalink to &quot;필터&quot;">​</a></h2><ul><li><strong>LEVEL</strong> 칩 — <strong>TRACE</strong>, <strong>DEBUG</strong>, <strong>INFO</strong>, <strong>SUCCESS</strong>, <strong>WARNING</strong>, <strong>ERROR</strong>, <strong>FATAL</strong>. 칩을 누르면 그 레벨이 숨겨지고, 다시 누르면 보입니다.</li><li><strong>PROC</strong> 칩 — 현재 소스에 나온 프로세스마다 하나씩 생기고, 색이 각각 다릅니다. 눌러서 숨기거나 다시 보이게 합니다.</li><li><strong>검색</strong> — 메시지 내용이나 프로세스 이름으로 걸러냅니다.</li><li>액션 바 오른쪽의 개수는 <em>표시 / 전체</em> <strong>줄</strong>입니다. 아주 긴 파일은 최신 2,500줄만 보여 주고, 맨 위에 그 사실을 알리는 안내가 붙습니다.</li></ul><h2 id="real-time" tabindex="-1">Real Time <a class="header-anchor" href="#real-time" aria-label="Permalink to &quot;Real Time&quot;">​</a></h2><ul><li><strong>자동스크롤</strong> — 최신 줄이 항상 보이게 합니다. 이전 줄을 읽으려면 끄세요.</li><li><strong>저장</strong> — 현재 필터된 줄을 기기에 저장합니다.</li><li>빨간 <strong>ERROR</strong> / <strong>FATAL</strong> 토스트를 누르거나 경고 배지 팝오버의 행을 누르면 이 탭이 열리고 해당 줄이 강조되어 앞뒤 상황을 볼 수 있습니다.</li></ul><h2 id="system-log" tabindex="-1">System Log <a class="header-anchor" href="#system-log" aria-label="Permalink to &quot;System Log&quot;">​</a></h2><p><img src="'+e+'" alt="System Log 탭"></p><ol><li><strong>불러오기</strong> — 로봇에서 날짜 목록을 가져옵니다(탭에 처음 들어가면 자동으로 실행되고 최신 날짜가 선택됩니다).</li><li><strong>DATE</strong> — 날짜를 고르면 파일을 불러와 위 필터를 적용해 보여 줍니다.</li><li><strong>타임라인 재생</strong> — 그날의 로그를 타임라인으로 재생합니다. 재생 / 일시정지, 이전·다음 줄로 이동, 위치 슬라이더, 0.25× … 16×, 60×, 300×를 차례로 오가는 배속 버튼이 있습니다(고배속은 조용한 구간을 건너뛰는 용도입니다). 줄을 누르면 그 시점으로 이동합니다. <strong>닫기</strong>로 목록으로 돌아갑니다.</li><li><strong>저장</strong> — 선택한 날짜의 원본 로그 파일을 기기에 저장합니다.</li></ol><h2 id="black-box" tabindex="-1">Black Box <a class="header-anchor" href="#black-box" aria-label="Permalink to &quot;Black Box&quot;">​</a></h2><p><img src="'+t+'" alt="Black Box 재생"></p><ol><li><strong>불러오기</strong> — 세션 목록을 가져옵니다(탭에 처음 들어가면 자동으로 실행됩니다).</li><li><strong>DATE</strong>와 <strong>SESSION</strong> — 기록을 고릅니다. 그날의 최신 세션이 먼저 열리고 재생 화면이 표시됩니다.</li><li><strong>타임라인 재생</strong> / <strong>로그 목록</strong> — 재생 화면과 그 세션의 일반 로그 목록을 전환합니다.</li><li><strong>지금 저장</strong> — 로봇에 지금 바로 블랙박스 세션을 기록하라고 요청합니다 — 이상한 일이 생긴 직후에 쓰십시오.</li><li><strong>zip 열기</strong> — 이 기기에 앞서 저장해 둔 세션 zip을 로봇 없이 재생합니다. <strong>닫기 — 로봇 세션으로</strong>를 누르면 로봇의 목록으로 돌아갑니다.</li><li><strong>zip 저장</strong> — 선택한 세션(데이터와 로그)을 기기에 저장합니다.</li></ol><h3 id="재생-화면" tabindex="-1">재생 화면 <a class="header-anchor" href="#재생-화면" aria-label="Permalink to &quot;재생 화면&quot;">​</a></h3><ul><li>헤더에 <strong>Black Box 재생</strong>과 길이·프레임 수·틱이 표시됩니다. 보기 버튼: <strong>분할</strong>(3D 자세 + 로그), <strong>4분할</strong>(데이터·로그·카메라·3D 칸), <strong>3D</strong>, <strong>데이터</strong>, <strong>영상</strong>(이벤트 클립만 크게), <strong>로그</strong>.</li><li><strong>카메라</strong> 칸에서는 그 순간의 <strong>이벤트 클립</strong>(전방·후방)이 재생되고, 재생 위치는 데이터 타임라인을 따라갑니다. 로봇이 아직 인코딩 중이면 클립이 도착하지 않을 수 있으니, 잠시 뒤 다시 시도하십시오. 내보낸 zip 에도 클립이 함께 들어 있어 로봇 없이 재생됩니다.</li><li><strong>Ref</strong>(3D 칸 우상단) — 참조 자세를 반투명 고스트로 겹쳐 명령 관절과 실측 관절을 비교할 수 있습니다.</li><li><strong>데이터</strong> 칸은 현재 프레임에 기록된 채널을 보여 줍니다. <em>miss</em> 칩은 제어 데드라인 미스 횟수입니다.</li><li>하단 바에는 이전 / 다음 프레임, 재생 / 일시정지, 슬라이더, 실제 시각과 프레임 카운터, 0.25× … 16×를 순환하는 배속 버튼이 있습니다.</li><li><strong>SYSTEM LOG</strong> 칸은 재생 위치를 따라 같이 스크롤됩니다. 줄을 누르면 그 시점으로 이동합니다. 기록에 시간 메타데이터가 없거나 시계가 어긋나면 <strong>시간동기 불확실</strong> 안내가 나타납니다.</li></ul><h2 id="find-errors" tabindex="-1">오류만 빠르게 훑기 <a class="header-anchor" href="#find-errors" aria-label="Permalink to &quot;오류만 빠르게 훑기 {#find-errors}&quot;">​</a></h2><p>하루치 로그에서 문제가 난 시각을 몇 초 만에 찾는 방법입니다.</p><ol><li><strong>LEVEL</strong> 칩에서 <code>TRACE</code> · <code>DEBUG</code> · <code>INFO</code> · <code>SUCCESS</code> · <code>WARNING</code> 을 눌러 <strong>숨깁니다.</strong><code>ERROR</code> 와 <code>FATAL</code> 만 남습니다.</li><li>타임라인 재생의 <strong>다음 줄</strong> 버튼을 반복해서 누릅니다 — 남아 있는 줄 사이만 건너뛰므로 오류에서 오류로 이동합니다.</li><li>멈춘 지점의 <strong>시각을 적어 둡니다</strong> (예: <code>19:30:48.855</code>).</li><li>앞뒤 맥락이 필요하면 그 자리에서 <code>WARNING</code> 이나 관련 <strong>PROC</strong> 칩을 다시 켜서 봅니다.</li></ol><p>문제가 어느 프로세스에서 시작됐는지 모를 때는 <strong>PROC</strong> 칩을 모두 켠 채로 훑고, 범위가 좁혀지면 그 프로세스만 남기세요.</p><h2 id="for-support" tabindex="-1">문의할 때 보낼 것 <a class="header-anchor" href="#for-support" aria-label="Permalink to &quot;문의할 때 보낼 것 {#for-support}&quot;">​</a></h2><p>아래 세 가지가 함께 오면 원인 파악이 훨씬 빨라집니다.</p><ol><li><strong>오류 메시지</strong> — 위 <a href="#find-errors">오류만 빠르게 훑기</a>로 찾은 <code>ERROR</code> · <code>FATAL</code> 목록. <strong>저장</strong>으로 파일을 남기거나 화면을 캡처합니다.</li><li><strong>발생 시각</strong> — 그 메시지의 시각을 함께 적어 주세요.</li><li><strong>그 시각 전후의 영상</strong> — 로봇이 무엇을 하고 있었는지 눈으로 보는 것만큼 확실한 것이 없습니다.</li></ol><p>소프트웨어 버전과 재현 단계까지 적어 주시면 더 좋습니다. 넘어짐이나 비상 정지처럼 순간적인 문제라면 <strong>zip 저장</strong>으로 남긴 <strong>Black Box 세션</strong>도 함께 보내 주세요.</p><p><strong>→ <a href="/RBQ/ko/manual/support/">기술지원 요청</a></strong></p><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li>로그 메시지의 배경이 되는 배터리·관절·센서 상태는 <a href="/RBQ/ko/manual/gui/dashboard.html">대시보드</a>에서 볼 수 있습니다.</li></ul>',29)])])}const b=r(g,[["render",i]]);export{f as __pageData,b as default};
